export default {"file":"admin-signup.html","title":"Schoolix - Super Admin Panel","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n\r\n<header class=\"workspace-header\">\r\n  <div class=\"workspace-brand\"><span class=\"brand-mark\">S</span><span>Schoolix</span><span class=\"workspace-label\">Super Admin Workspace</span></div>\r\n  <div class=\"super-admin-top-actions\"><button type=\"button\" class=\"super-admin-logout\" onclick=\"logoutSuperAdmin()\">Sign out</button></div>\r\n</header>\r\n\r\n<div class=\"shell\">\r\n\r\n  <!-- LEFT: Hero + School List -->\r\n  <section class=\"panel hero\">\r\n    <div class=\"panel-body\">\r\n      <div class=\"eyebrow\">Operations overview</div>\r\n      <h1>School portfolio</h1>\r\n      <p>Manage access, subscriptions, billing records and modules for every school from one workspace.</p>\r\n      <div class=\"admin-summary\" aria-label=\"Portfolio summary\">\r\n        <div class=\"summary-cell\"><span>Total schools</span><strong id=\"summaryTotal\">0</strong></div>\r\n        <div class=\"summary-cell\"><span>Active</span><strong id=\"summaryActive\">0</strong></div>\r\n        <div class=\"summary-cell\"><span>Need attention</span><strong id=\"summaryAttention\">0</strong></div>\r\n        <div class=\"summary-cell\"><span>Modules controlled</span><strong>11</strong></div>\r\n      </div>\r\n\r\n      <div class=\"list-head\">\r\n        <h3>Schools With Access</h3>\r\n        <span class=\"count-badge\" id=\"schoolCount\">0 schools</span>\r\n      </div>\r\n      <div class=\"school-toolbar\">\r\n        <input id=\"schoolSearch\" class=\"school-search\" type=\"search\" placeholder=\"Search by school or admin email\">\r\n        <select id=\"schoolStatusFilter\" class=\"school-filter\"><option value=\"all\">All status</option><option value=\"active\">Active</option><option value=\"attention\">Needs attention</option><option value=\"blocked\">Blocked</option></select>\r\n      </div>\r\n\r\n      <div class=\"school-list\" id=\"schoolList\">\r\n        <div class=\"empty-state\">Loading schools...</div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- RIGHT: Signup Form -->\r\n  <section class=\"panel form-panel\">\r\n    <div class=\"panel-body\">\r\n      <div class=\"eyebrow\">New school</div>\r\n      <h2>Create school workspace</h2>\r\n      <p class=\"sub\">Set up the school administrator, branding and first subscription in one step.</p>\r\n\r\n      <div class=\"form-grid\">\r\n        <div class=\"field\">\r\n          <label for=\"schoolName\">School Name</label>\r\n          <input type=\"text\" id=\"schoolName\" placeholder=\"e.g. Delhi Public School\" required>\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"adminName\">Admin Name</label>\r\n          <input type=\"text\" id=\"adminName\" placeholder=\"Full name\" required>\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"email\">Email Address</label>\r\n          <input type=\"email\" id=\"email\" placeholder=\"admin@school.com\" required>\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"password\">Password</label>\r\n          <input type=\"password\" id=\"password\" placeholder=\"Minimum 6 characters\" required>\r\n        </div>\r\n        <div class=\"logo-upload-row\">\r\n          <div class=\"school-logo-preview\" id=\"schoolLogoPreview\">LOGO</div>\r\n          <div class=\"logo-upload-copy\">\r\n            <label for=\"schoolLogo\">School Photo / Logo</label>\r\n            <input type=\"file\" id=\"schoolLogo\" accept=\"image/*\" onchange=\"previewSchoolLogo(event)\">\r\n            <small>This logo will appear for that school's admin, teachers, students and parents.</small>\r\n          </div>\r\n        </div>\r\n        <div class=\"hint\">\r\n          New admin gets access to all features by default. You can restrict individual features anytime from the school list.\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"signupPlan\">Subscription Plan</label>\r\n          <select id=\"signupPlan\"><option value=\"Starter\">Starter</option><option value=\"Growth\" selected>Growth</option><option value=\"Enterprise\">Enterprise</option></select>\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"signupExpiry\">Licence Expiry</label>\r\n          <input type=\"date\" id=\"signupExpiry\" required>\r\n        </div>\r\n        <button class=\"submit-btn\" onclick=\"signup()\">Create Admin Account</button>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n</div>\r\n\r\n<!-- FEATURE CONTROL MODAL -->\r\n<div class=\"modal-overlay\" id=\"featureModal\">\r\n  <div class=\"modal\">\r\n    <div class=\"modal-header\">\r\n      <div>\r\n        <div class=\"modal-title\" id=\"modalSchoolName\">School Name</div>\r\n        <div class=\"modal-sub\" id=\"modalSchoolEmail\">admin@school.com</div>\r\n      </div>\r\n      <button class=\"modal-close\" onclick=\"closeModal()\" aria-label=\"Close\">x</button>\r\n    </div>\r\n\r\n    <div class=\"modal-body\">\r\n      <div class=\"modal-brand-row\">\r\n        <div class=\"modal-logo\" id=\"modalSchoolLogo\">S</div>\r\n        <div>\r\n          <div class=\"features-head\" style=\"margin:0 0 4px;\">School Intelligence</div>\r\n          <div class=\"modal-sub\" id=\"modalSchoolHealth\">Loading live school metrics...</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"insight-grid\" id=\"schoolInsightGrid\"></div>\r\n      <div class=\"control-note\">\r\n        Firebase billable read/write counts are not exposed per school directly in this client panel. The counters below show app data activity available inside Schoolix, and the Operations Audit module can be wired for future per-action counters.\r\n      </div>\r\n\r\n      <!-- Master Access Toggle -->\r\n      <div class=\"access-row\">\r\n        <div class=\"access-row-info\">\r\n          <strong>Platform Access</strong>\r\n          <span>Block or allow this school from logging in</span>\r\n        </div>\r\n        <div class=\"toggle-wrap\">\r\n          <span class=\"toggle-label-text\" id=\"accessLabel\">Disabled</span>\r\n          <label class=\"toggle\">\r\n            <input type=\"checkbox\" id=\"masterAccessToggle\" onchange=\"updateAccessLabel()\">\r\n            <span class=\"slider-track\"></span>\r\n          </label>\r\n        </div>\r\n      </div>\r\n\r\n      <section class=\"school-profile-panel\" aria-label=\"School profile controls\">\r\n        <h3>School profile</h3>\r\n        <p>Update the school information shown throughout Schoolix. The login email is visible here but is changed through a separate secure credential process.</p>\r\n        <div class=\"school-profile-grid\">\r\n          <label>School name<input id=\"profileSchoolName\" type=\"text\" maxlength=\"120\"></label>\r\n          <label>Administrator name<input id=\"profileAdminName\" type=\"text\" maxlength=\"100\"></label>\r\n          <label>Login email<input id=\"profileAdminEmail\" class=\"profile-readonly\" type=\"email\" readonly></label>\r\n          <label>Contact number<input id=\"profilePhone\" type=\"tel\" maxlength=\"30\" placeholder=\"School contact number\"></label>\r\n          <label>School code<input id=\"profileSchoolCode\" type=\"text\" maxlength=\"40\" placeholder=\"Optional internal code\"></label>\r\n          <label>Replace logo<input id=\"profileSchoolLogo\" type=\"file\" accept=\"image/*\"></label>\r\n          <label class=\"profile-wide\">Address<textarea id=\"profileAddress\" maxlength=\"300\" placeholder=\"School address, city and state\"></textarea></label>\r\n        </div>\r\n      </section>\r\n\r\n      <section class=\"subscription-panel\" aria-label=\"Subscription and billing controls\">\r\n        <h3>Subscription & Billing Control</h3>\r\n        <p>Expiry automatically blocks every school user at their next protected page check. Set a manual suspension anytime.</p>\r\n        <div class=\"subscription-grid\">\r\n          <label>Plan<select id=\"subscriptionPlan\"><option value=\"Starter\">Starter</option><option value=\"Growth\">Growth</option><option value=\"Enterprise\">Enterprise</option></select></label>\r\n          <label>Status<select id=\"subscriptionStatus\"><option value=\"active\">Active</option><option value=\"past_due\">Payment due</option><option value=\"suspended\">Suspended</option><option value=\"cancelled\">Cancelled</option></select></label>\r\n          <label>Expiry date<input id=\"subscriptionExpiresAt\" type=\"date\"></label>\r\n          <label>Billing amount (₹)<input id=\"paymentAmount\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"Optional renewal payment\"></label>\r\n          <label>Payment date<input id=\"paymentDate\" type=\"date\"></label>\r\n          <label>Reference / note<input id=\"paymentReference\" maxlength=\"100\" placeholder=\"Invoice or transaction ID\"></label>\r\n        </div>\r\n        <div class=\"subscription-summary\" id=\"subscriptionSummary\">Loading subscription...</div>\r\n        <div class=\"billing-history\"><h4>Recent payment records</h4><div id=\"billingHistory\"><div class=\"billing-empty\">Loading records...</div></div></div>\r\n      </section>\r\n\r\n      <!-- Feature Toggles -->\r\n      <div class=\"features-head\">Module-Level Control</div>\r\n      <div class=\"features-grid\" id=\"featuresGrid\"></div>\r\n    </div>\r\n\r\n    <div class=\"modal-footer\">\r\n      <button class=\"btn-cancel\" onclick=\"closeModal()\">Cancel</button>\r\n      <button class=\"btn-save\" onclick=\"saveFeatures()\">Save Changes</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Toast -->\r\n<div class=\"toast\" id=\"toast\"></div>\r\n\r\n<script type=\"module\">\r\nimport { initializeApp }\r\n  from \"./firebase-compat.js\";\r\nimport { getAuth, createUserWithEmailAndPassword, onAuthStateChanged, signOut }\r\n  from \"./firebase-compat.js\";\r\nimport {\r\n  getFirestore, doc, setDoc, collection,\r\n  getDocs, updateDoc, deleteDoc, getDoc, query, where, limit\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\nconst db = getFirestore(app);\nconst adminCreatorApp = initializeApp(firebaseConfig, \"superAdminCreatorApp\");\nconst adminCreatorAuth = getAuth(adminCreatorApp);\nconst SUPER_ADMIN_EMAIL = \"anshbajpai4@gmail.com\";\nconst SUPABASE_URL = \"https://ezkmeedcqetztkeppxil.supabase.co\";\nconst SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\nconst CREATE_SCHOOL_ADMIN_URL = `${SUPABASE_URL}/functions/v1/create-school-admin`;\n\r\n// ---- FEATURE DEFINITIONS ----\r\nconst ICONS = {\r\n  dashboard: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 13h4v7H4v-7Zm6-9h4v16h-4V4Zm6 5h4v11h-4V9Z\"/></svg>`,\r\n  teachers: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-8 8a8 8 0 0 1 16 0H4Z\"/></svg>`,\r\n  students: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3 2 8l10 5 10-5-10-5Zm-7 9v4l7 4 7-4v-4l-7 3.5L5 12Z\"/></svg>`,\r\n  attendance: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 3h10v2h3v16H4V5h3V3Zm2 4H6v12h12V7h-3v2H9V7Zm1 6h6v2h-6v-2Z\"/></svg>`,\r\n  payroll: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 6h16v12H4V6Zm2 2v8h12V8H6Zm6 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z\"/></svg>`,\r\n  library: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 4h12a2 2 0 0 1 2 2v14H7a2 2 0 0 1-2-2V4Zm2 0v14h10V6H7Zm2 4h6v2H9V8Z\"/></svg>`,\r\n  timetable: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 2h2v3h6V2h2v3h3v17H4V5h3V2Zm-1 8v10h12V10H6Zm2 2h3v3H8v-3Z\"/></svg>`,\r\n  transport: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 4h12l2 5v8h-2a2 2 0 0 1-4 0h-4a2 2 0 0 1-4 0H4V9l2-5Zm1.2 2L6.4 8h11.2l-.8-2H7.2Z\"/></svg>`,\r\n  reports: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 5h7l2 2h7v12H4V5Zm3 8h10v-2H7v2Zm0 4h7v-2H7v2Z\"/></svg>`,\r\n  announcements: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 10v4h4l7 4V6l-7 4H4Zm13-1.5v7a4 4 0 0 0 0-7Z\"/></svg>`,\r\n  settings: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m19.4 13.5.1-1.5-.1-1.5 2-1.5-2-3.5-2.4 1a8 8 0 0 0-2.6-1.5L14 2h-4l-.4 2.5A8 8 0 0 0 7 6L4.6 5l-2 3.5 2 1.5-.1 1.5.1 1.5-2 1.5 2 3.5 2.4-1a8 8 0 0 0 2.6 1.5L10 22h4l.4-2.5A8 8 0 0 0 17 18l2.4 1 2-3.5-2-1.5ZM12 15.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7Z\"/></svg>`\r\n};\r\n\r\nconst FEATURES = [\r\n  { key: \"dashboard\",      label: \"Dashboard\",      desc: \"Main overview & stats\",       icon: ICONS.dashboard, color: \"rgba(59,110,248,0.12)\"  },\r\n  { key: \"teachers\",       label: \"Teachers\",        desc: \"Teacher management module\",   icon: ICONS.teachers, color: \"rgba(168,85,247,0.12)\" },\r\n  { key: \"students\",       label: \"Students\",        desc: \"Student records & profiles\",  icon: ICONS.students, color: \"rgba(20,184,166,0.12)\"  },\r\n  { key: \"attendance\",     label: \"Attendance\",      desc: \"Daily attendance tracking\",   icon: ICONS.attendance, color: \"rgba(245,158,11,0.12)\"  },\r\n  { key: \"payroll\",        label: \"Payroll\",         desc: \"Salary & payment processing\", icon: ICONS.payroll, color: \"rgba(34,197,94,0.12)\"   },\r\n  { key: \"library\",        label: \"Library\",         desc: \"Books, issues and returns\",    icon: ICONS.library, color: \"rgba(14,165,233,0.12)\"   },\r\n  { key: \"timetable\",      label: \"Timetable\",       desc: \"Class and teacher schedules\",  icon: ICONS.timetable, color: \"rgba(236,72,153,0.12)\" },\r\n  { key: \"transport\",      label: \"Transport\",       desc: \"Vehicles, routes and tracking\", icon: ICONS.transport, color: \"rgba(132,204,22,0.12)\" },\r\n  { key: \"reports\",        label: \"Reports\",         desc: \"Analytics & report exports\",  icon: ICONS.reports, color: \"rgba(239,68,68,0.12)\"   },\r\n  { key: \"announcements\",  label: \"Announcements\",   desc: \"School-wide notices\",         icon: ICONS.announcements, color: \"rgba(99,102,241,0.12)\"  },\r\n  { key: \"settings\",       label: \"Settings\",        desc: \"School config & branding\",    icon: ICONS.settings, color: \"rgba(100,116,139,0.12)\" },\r\n];\r\n// ---- CURRENT MODAL STATE ----\r\nlet currentUID = null;\r\nlet currentData = null;\r\nlet signupInProgress = false;\r\nconst CLOUDINARY_CLOUD_NAME = \"fthnumnk\";\r\nconst CLOUDINARY_UPLOAD_PRESET = \"schoolix_student_photos\";\r\n\r\nfunction isoDate(value) {\r\n  const date = toJsDate(value);\r\n  return date ? date.toISOString().slice(0, 10) : \"\";\r\n}\r\n\r\nfunction defaultExpiryDate() {\r\n  const date = new Date();\r\n  date.setFullYear(date.getFullYear() + 1);\r\n  return date.toISOString().slice(0, 10);\r\n}\r\n\r\nfunction subscriptionState(data = {}) {\r\n  const subscription = data.subscription || {};\r\n  const expiresAt = isoDate(subscription.expiresAt || data.subscriptionExpiresAt);\r\n  const status = String(subscription.status || \"active\").toLowerCase();\r\n  const expired = Boolean(expiresAt && new Date(`${expiresAt}T23:59:59`).getTime() < Date.now());\r\n  const blocked = [\"suspended\", \"cancelled\"].includes(status) || expired;\r\n  return { plan: subscription.plan || \"Growth\", status: expired ? \"expired\" : status, expiresAt, expired, blocked };\r\n}\r\n\r\nfunction subscriptionLabel(data = {}) {\r\n  const sub = subscriptionState(data);\r\n  if (sub.status === \"expired\") return `Expired ${sub.expiresAt || \"\"}`.trim();\r\n  if (sub.status === \"suspended\") return \"Suspended\";\r\n  if (sub.status === \"past_due\") return \"Payment due\";\r\n  if (sub.status === \"cancelled\") return \"Cancelled\";\r\n  return `Active · expires ${sub.expiresAt || \"not set\"}`;\r\n}\r\n\r\nfunction normalizeEmail(value = \"\") {\r\n  return String(value || \"\").trim().toLowerCase();\r\n}\r\n\r\nfunction isAuthorizedSuperAdmin(user) {\r\n  return normalizeEmail(user?.email) === SUPER_ADMIN_EMAIL;\r\n}\r\n\r\nfunction redirectUnauthorized() {\r\n  resetSchoolList(\"Super admin login required.\");\r\n  window.setTimeout(() => {\r\n    window.location.replace(\"#/index.html?access_error=\" + encodeURIComponent(\"Only the authorized Super Admin can access this page.\"));\r\n  }, 250);\r\n}\r\n\r\nfunction escapeHtml(value = \"\") {\r\n  return String(value ?? \"\")\r\n    .replace(/&/g, \"&amp;\")\r\n    .replace(/</g, \"&lt;\")\r\n    .replace(/>/g, \"&gt;\")\r\n    .replace(/\"/g, \"&quot;\")\r\n    .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction jsString(value = \"\") {\r\n  return String(value ?? \"\").replace(/\\\\/g, \"\\\\\\\\\").replace(/'/g, \"\\\\'\").replace(/\\n/g, \" \");\r\n}\r\n\r\nfunction renderLogo(url = \"\", fallback = \"S\") {\r\n  const safeUrl = String(url || \"\").trim();\r\n  return safeUrl ? `<img src=\"${escapeHtml(safeUrl)}\" alt=\"School logo\">` : escapeHtml(fallback || \"S\");\r\n}\r\n\r\nwindow.previewSchoolLogo = (event) => {\r\n  const file = event.target.files?.[0];\r\n  const preview = document.getElementById(\"schoolLogoPreview\");\r\n  if (!preview) return;\r\n  if (!file) {\r\n    preview.textContent = \"LOGO\";\r\n    return;\r\n  }\r\n  preview.innerHTML = `<img src=\"${URL.createObjectURL(file)}\" alt=\"School logo preview\">`;\r\n};\r\n\r\nasync function uploadSchoolLogo(file, schoolName) {\r\n  if (!file) return { logoUrl: \"\", logoPublicId: \"\" };\r\n  if (!file.type.startsWith(\"image/\")) throw new Error(\"Please select an image file for school logo.\");\r\n  if (file.size > 5 * 1024 * 1024) throw new Error(\"School logo must be under 5 MB.\");\r\n  const form = new FormData();\r\n  form.append(\"file\", file);\r\n  form.append(\"upload_preset\", CLOUDINARY_UPLOAD_PRESET);\r\n  form.append(\"folder\", \"schoolix/school_logos\");\r\n  form.append(\"public_id\", `${schoolName.replace(/[^a-zA-Z0-9_-]/g, \"_\")}_${Date.now()}`);\r\n  const response = await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(CLOUDINARY_CLOUD_NAME)}/image/upload`, {\r\n    method: \"POST\",\r\n    body: form\r\n  });\r\n  const data = await response.json().catch(() => ({}));\r\n  if (!response.ok) throw new Error(data.error?.message || \"School logo upload failed.\");\r\n  return { logoUrl: data.secure_url || data.url || \"\", logoPublicId: data.public_id || \"\" };\r\n}\r\n\r\n// ---- TOAST ----\r\nfunction showToast(msg, type = \"success\") {\r\n  const t = document.getElementById(\"toast\");\r\n  t.textContent = msg;\r\n  t.className = \"toast \" + type + \" show\";\r\n  setTimeout(() => t.className = \"toast\", 2800);\r\n}\r\n\r\nwindow.logoutSuperAdmin = async () => {\r\n  try {\r\n    await signOut(auth);\r\n    window.location.replace(\"#/index.html\");\r\n  } catch (error) {\r\n    showToast(error.message || \"Unable to logout.\", \"error\");\r\n  }\r\n};\r\n\r\n// ---- INITIALS ----\r\nfunction initials(name = \"\") {\r\n  return name.trim().split(\" \").slice(0,2).map(w => w[0]?.toUpperCase() || \"\").join(\"\");\r\n}\r\n\r\n// ---- SIGNUP ----\r\nwindow.signup = async () => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) {\r\n    showToast(\"Only authorized Super Admin can create schools.\", \"error\");\r\n    return;\r\n  }\r\n  if (signupInProgress) return;\r\n  const schoolName = document.getElementById(\"schoolName\").value.trim();\r\n  const adminName  = document.getElementById(\"adminName\").value.trim();\r\n  const email      = normalizeEmail(document.getElementById(\"email\").value);\r\n  const password   = document.getElementById(\"password\").value;\r\n  const logoFile   = document.getElementById(\"schoolLogo\")?.files?.[0] || null;\r\n  const plan = document.getElementById(\"signupPlan\").value;\r\n  const expiresAt = document.getElementById(\"signupExpiry\").value;\r\n\r\n  if (!schoolName || !adminName || !email || !password) {\r\n    showToast(\"Please fill all fields\", \"error\"); return;\r\n  }\r\n  if (password.length < 6) {\r\n    showToast(\"Password must be at least 6 characters\", \"error\"); return;\r\n  }\r\n  if (!expiresAt) {\r\n    showToast(\"Please set the school licence expiry date\", \"error\"); return;\r\n  }\r\n\r\n  const btn = document.querySelector(\".submit-btn\");\r\n  btn.textContent = \"Creating...\";\r\n  btn.disabled = true;\r\n  signupInProgress = true;\r\n\r\n  try {\r\n    const existing = await getDocs(query(collection(db, \"users\"), where(\"email\", \"==\", email), limit(1)));\r\n    if (!existing.empty) {\r\n      showToast(\"This admin email already has a school account.\", \"error\");\r\n      return;\r\n    }\r\n\r\n    // Default: all features ON\n    const defaultFeatures = {};\n    FEATURES.forEach(f => defaultFeatures[f.key] = true);\n\n    const logoUpload = await uploadSchoolLogo(logoFile, schoolName);\n    const token = await auth.currentUser?.getIdToken(true);\n    if (!token) throw new Error(\"Super admin session expired. Please login again.\");\n    const response = await fetch(CREATE_SCHOOL_ADMIN_URL, {\n      method: \"POST\",\n      headers: {\n        \"Content-Type\": \"application/json\",\n        \"apikey\": SUPABASE_ANON_KEY,\n        \"Authorization\": `Bearer ${token}`\n      },\n      body: JSON.stringify({\n        schoolName,\n        adminName,\n        email,\n        password,\n        logoUrl: logoUpload.logoUrl,\n        schoolLogoUrl: logoUpload.logoUrl,\n        logoPublicId: logoUpload.logoPublicId,\n        features: defaultFeatures,\r\n        subscription: { plan, status: \"active\", expiresAt }\r\n      })\n    });\n    const result = await response.json().catch(() => ({}));\n    if (!response.ok || !result.success) throw new Error(result.error || \"Unable to create admin account.\");\n\n    await setDoc(doc(db, \"schools\", result.uid), {\n      schoolName,\n      name: schoolName,\n      adminName,\n      adminEmail: email,\n      logoUrl: logoUpload.logoUrl,\r\n      schoolLogoUrl: logoUpload.logoUrl,\r\n      logoPublicId: logoUpload.logoPublicId,\r\n      access: true,\r\n      features: defaultFeatures,\r\n      subscription: { plan, status: \"active\", expiresAt },\r\n      onboardingRequired: true,\r\n      onboardingCompleted: false,\r\n      onboardingVersion: 1,\r\n      createdAt: new Date(),\r\n      createdBy: auth.currentUser?.uid || \"\",\r\n      createdByEmail: SUPER_ADMIN_EMAIL\n    }, { merge: true });\n    await setDoc(doc(db, \"users\", result.uid), {\r\n      access: true,\r\n      features: defaultFeatures,\r\n      subscription: { plan, status: \"active\", expiresAt },\r\n      updatedAt: new Date()\r\n    }, { merge: true });\r\n\n    showToast(`Admin created for ${schoolName}`);\n    [\"schoolName\",\"adminName\",\"email\",\"password\"].forEach(id => document.getElementById(id).value = \"\");\r\n    document.getElementById(\"signupExpiry\").value = defaultExpiryDate();\r\n    const logoInput = document.getElementById(\"schoolLogo\");\r\n    if (logoInput) logoInput.value = \"\";\r\n    const logoPreview = document.getElementById(\"schoolLogoPreview\");\r\n    if (logoPreview) logoPreview.textContent = \"LOGO\";\r\n    loadSchools();\r\n  } catch(e) {\r\n    showToast(e.message, \"error\");\r\n  } finally {\r\n    await signOut(adminCreatorAuth).catch(() => {});\r\n    signupInProgress = false;\r\n    btn.textContent = \"Create Admin Account\";\r\n    btn.disabled = false;\r\n  }\r\n};\r\n\r\nfunction resetSchoolList(message = \"Loading...\") {\r\n  const list = document.getElementById(\"schoolList\");\r\n  const countBadge = document.getElementById(\"schoolCount\");\r\n  countBadge.textContent = \"0 schools\";\r\n  list.innerHTML = `<div class=\"empty-state\">${message}</div>`;\r\n}\r\n\r\nfunction toJsDate(value) {\r\n  if (!value) return null;\r\n  if (typeof value.toDate === \"function\") return value.toDate();\r\n  if (typeof value.seconds === \"number\") return new Date(value.seconds * 1000);\r\n  const parsed = new Date(value);\r\n  return Number.isNaN(parsed.getTime()) ? null : parsed;\r\n}\r\n\r\nfunction isToday(value) {\r\n  const date = toJsDate(value);\r\n  if (!date) return false;\r\n  const today = new Date();\r\n  return date.getFullYear() === today.getFullYear() &&\r\n    date.getMonth() === today.getMonth() &&\r\n    date.getDate() === today.getDate();\r\n}\r\n\r\nasync function countCollection(pathParts) {\r\n  try {\r\n    const snap = await getDocs(collection(db, ...pathParts));\r\n    return snap.size;\r\n  } catch (_) {\r\n    return 0;\r\n  }\r\n}\r\n\r\nfunction teacherCountKey(data = {}, fallbackId = \"\") {\r\n  return String(\r\n    data.authUid ||\r\n    data.uid ||\r\n    data.teacherId ||\r\n    data.email ||\r\n    fallbackId ||\r\n    \"\"\r\n  ).trim().toLowerCase();\r\n}\r\n\r\nasync function countTeachersForSchool(uid, teachersSnap) {\r\n  const teacherKeys = new Set();\r\n  (teachersSnap.docs || []).forEach((item) => {\r\n    const key = teacherCountKey(item.data?.() || {}, item.id);\r\n    if (key) teacherKeys.add(key);\r\n  });\r\n\r\n  const userQueries = [\"teacher\", \"teachers\"].flatMap((teacherRole) => [\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminId\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"schoolId\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminUID\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminUid\", \"==\", uid))\r\n  ]);\r\n\r\n  const userSnaps = await Promise.all(userQueries.map((teacherQuery) => getDocs(teacherQuery).catch(() => ({ docs: [] }))));\r\n  userSnaps.forEach((snap) => {\r\n    (snap.docs || []).forEach((item) => {\r\n      const data = item.data?.() || {};\r\n      const key = teacherCountKey(data, item.id);\r\n      if (key) teacherKeys.add(key);\r\n    });\r\n  });\r\n\r\n  return teacherKeys.size;\r\n}\r\n\r\nasync function loadSchoolMetrics(uid) {\r\n  const [\r\n    studentsSnap,\r\n    teachersSnap,\r\n    attendanceSnap,\r\n    feesSnap,\r\n    reportsSnap,\r\n    notificationsSnap,\r\n    devicesSnap,\r\n    accountsSnap\r\n  ] = await Promise.all([\r\n    getDocs(collection(db, \"schools\", uid, \"students\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"teachers\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"attendance\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"fees\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"reportCards\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"notifications\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"notificationDevices\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"accounts\")).catch(() => ({ docs: [], size: 0 }))\r\n  ]);\r\n  const attendanceRows = attendanceSnap.docs.map((item) => item.data());\r\n  const notificationRows = notificationsSnap.docs.map((item) => item.data());\r\n  const todayAttendance = attendanceRows.filter((item) => isToday(item.date || item.timestamp || item.createdAt));\r\n  const todayAbsent = todayAttendance.filter((item) => String(item.status || \"\").toLowerCase() === \"absent\");\r\n  const todayEmails = attendanceRows.filter((item) => item.absenceEmailSent === true && isToday(item.absenceEmailSentAt || item.timestamp || item.date));\r\n  const todayNotifications = notificationRows.filter((item) => isToday(item.createdAt));\r\n  const writeEstimate = todayAttendance.length + todayNotifications.length + todayEmails.length;\r\n  const teacherCount = await countTeachersForSchool(uid, teachersSnap);\r\n  return {\r\n    students: studentsSnap.size,\r\n    teachers: teacherCount,\r\n    attendance: attendanceSnap.size,\r\n    todayAttendance: todayAttendance.length,\r\n    todayAbsent: todayAbsent.length,\r\n    todayEmails: todayEmails.length,\r\n    fees: feesSnap.size,\r\n    reports: reportsSnap.size,\r\n    notifications: notificationsSnap.size,\r\n    todayNotifications: todayNotifications.length,\r\n    devices: devicesSnap.size,\r\n    accounts: accountsSnap.size,\r\n    writeEstimate\r\n  };\r\n}\r\n\r\nfunction renderInsightGrid(metrics = {}) {\r\n  const rows = [\r\n    [\"Students\", metrics.students || 0],\r\n    [\"Teachers\", metrics.teachers || 0],\r\n    [\"Today attendance\", metrics.todayAttendance || 0],\r\n    [\"Today absent\", metrics.todayAbsent || 0],\r\n    [\"Emails today\", metrics.todayEmails || 0],\r\n    [\"Push today\", metrics.todayNotifications || 0],\r\n    [\"Reports\", metrics.reports || 0],\r\n    [\"Fee records\", metrics.fees || 0],\r\n    [\"Devices\", metrics.devices || 0],\r\n    [\"Accounts\", metrics.accounts || 0],\r\n    [\"Audit writes est.\", metrics.writeEstimate || 0],\r\n    [\"Total attendance\", metrics.attendance || 0]\r\n  ];\r\n  return rows.map(([label, value]) => `<div class=\"insight-card\"><span>${label}</span><strong>${Number(value || 0).toLocaleString(\"en-IN\")}</strong></div>`).join(\"\");\r\n}\r\n\r\nfunction updatePortfolioSummary(schools = []) {\r\n  const active = schools.filter((school) => school.access !== false && !subscriptionState(school).blocked).length;\r\n  const attention = schools.filter((school) => {\r\n    const state = subscriptionState(school);\r\n    return state.status === \"past_due\" || state.expired || state.blocked || school.access === false;\r\n  }).length;\r\n  document.getElementById(\"summaryTotal\").textContent = schools.length.toLocaleString(\"en-IN\");\r\n  document.getElementById(\"summaryActive\").textContent = active.toLocaleString(\"en-IN\");\r\n  document.getElementById(\"summaryAttention\").textContent = attention.toLocaleString(\"en-IN\");\r\n}\r\n\r\nfunction applySchoolFilters() {\r\n  const search = String(document.getElementById(\"schoolSearch\")?.value || \"\").trim().toLowerCase();\r\n  const filter = String(document.getElementById(\"schoolStatusFilter\")?.value || \"all\");\r\n  document.querySelectorAll(\".school-card\").forEach((card) => {\r\n    const matchesSearch = !search || String(card.dataset.search || \"\").includes(search);\r\n    const matchesStatus = filter === \"all\" || card.dataset.status === filter;\r\n    card.hidden = !(matchesSearch && matchesStatus);\r\n  });\r\n}\r\n\r\n// ---- LOAD SCHOOLS ----\r\nasync function loadSchools() {\r\n  const list = document.getElementById(\"schoolList\");\r\n  const countBadge = document.getElementById(\"schoolCount\");\r\n  list.innerHTML = `<div class=\"empty-state\">Loading...</div>`;\r\n\r\n  try {\r\n    const snap = await getDocs(collection(db, \"users\"));\r\n    const schools = [];\r\n    snap.forEach(d => {\r\n      const data = d.data();\r\n      if (data.schoolName && String(data.role || \"\").toLowerCase() === \"admin\") schools.push({ uid: d.id, ...data });\r\n    });\r\n\r\n    countBadge.textContent = schools.length + \" school\" + (schools.length !== 1 ? \"s\" : \"\");\r\n    updatePortfolioSummary(schools);\r\n\r\n    if (!schools.length) {\r\n      list.innerHTML = `<div class=\"empty-state\">No schools registered yet.</div>`;\r\n      return;\r\n    }\r\n\r\n    const metricEntries = await Promise.all(schools.map(async (school) => [school.uid, await loadSchoolMetrics(school.uid)]));\r\n    const metricsBySchool = Object.fromEntries(metricEntries);\r\n\r\n    list.innerHTML = schools.map(s => {\r\n      const subscription = subscriptionState(s);\r\n      const on = s.access !== false && !subscription.blocked;\r\n      const portfolioStatus = !on ? \"blocked\" : (subscription.status === \"past_due\" ? \"attention\" : \"active\");\r\n      const ini = initials(s.schoolName);\r\n      const featOn = s.features ? Object.values(s.features).filter(Boolean).length : FEATURES.length;\r\n      const metrics = metricsBySchool[s.uid] || {};\r\n      return `\r\n      <div class=\"school-card\" id=\"card-${s.uid}\" data-status=\"${portfolioStatus}\" data-search=\"${escapeHtml(`${s.schoolName || \"\"} ${s.email || \"\"} ${s.adminEmail || \"\"}`).toLowerCase()}\">\r\n        <div class=\"card-main\">\r\n          <div class=\"school-avatar\">${renderLogo(s.logoUrl || s.schoolLogoUrl || \"\", ini)}</div>\r\n          <div class=\"card-info\">\r\n            <div class=\"card-name\">${escapeHtml(s.schoolName)}</div>\r\n            <div class=\"card-meta\">\r\n              <span class=\"status-dot ${on ? 'on' : 'off'}\"></span>\r\n              ${on ? \"Access Enabled\" : \"Access blocked\"} &nbsp;|&nbsp;\r\n              ${featOn}/${FEATURES.length} modules\r\n            </div>\r\n            <div class=\"card-meta\" style=\"margin-top:4px;color:${subscription.blocked ? '#f87171' : '#94a3b8'}\">${escapeHtml(subscriptionLabel(s))}</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"school-card-stats\">\r\n          <div class=\"school-card-stat\"><strong>${metrics.students || 0}</strong><span>Students</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.teachers || 0}</strong><span>Teachers</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.todayEmails || 0}</strong><span>Mails today</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.writeEstimate || 0}</strong><span>Ops today</span></div>\r\n        </div>\r\n        <div class=\"card-actions\">\r\n          <button class=\"btn ${on ? 'btn-toggle-on' : 'btn-toggle-off'}\"\r\n            onclick=\"quickToggle('${s.uid}', ${on})\">\r\n            ${on ? \"Disable\" : \"Enable\"}\r\n          </button>\r\n          <button class=\"btn btn-features\"\r\n            onclick=\"openModal('${s.uid}')\">\r\n            Manage school\r\n          </button>\r\n          <button class=\"btn btn-delete\"\r\n            onclick=\"deleteSchool('${s.uid}', '${jsString(s.schoolName)}')\">\r\n            Delete\r\n          </button>\r\n        </div>\r\n      </div>`;\r\n    }).join(\"\");\r\n    applySchoolFilters();\r\n  } catch(e) {\r\n    list.innerHTML = `<div class=\"empty-state\">Failed to load schools.</div>`;\r\n    console.error(e);\r\n  }\r\n}\r\n\r\n// ---- QUICK TOGGLE ACCESS ----\r\nwindow.quickToggle = async (uid, currentAccess) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  try {\r\n    await updateDoc(doc(db, \"users\", uid), { access: !currentAccess });\r\n    await setDoc(doc(db, \"schools\", uid), { access: !currentAccess, updatedAt: new Date() }, { merge: true });\r\n    showToast(currentAccess ? \"Access disabled\" : \"Access enabled\");\r\n    loadSchools();\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\n// ---- OPEN MODAL ----\r\nwindow.openModal = async (uid) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  currentUID = uid;\r\n  try {\r\n    const snap = await getDoc(doc(db, \"users\", uid));\r\n    if (!snap.exists()) { showToast(\"School not found\", \"error\"); return; }\r\n    const schoolSnap = await getDoc(doc(db, \"schools\", uid)).catch(() => null);\r\n    currentData = { ...(schoolSnap?.exists?.() ? schoolSnap.data() : {}), ...snap.data() };\r\n\r\n    document.getElementById(\"modalSchoolName\").textContent = currentData.schoolName;\r\n    document.getElementById(\"modalSchoolEmail\").textContent = currentData.email;\r\n    document.getElementById(\"modalSchoolLogo\").innerHTML = renderLogo(currentData.logoUrl || currentData.schoolLogoUrl || \"\", initials(currentData.schoolName));\r\n    document.getElementById(\"schoolInsightGrid\").innerHTML = `<div class=\"empty-state\" style=\"grid-column:1/-1;\">Loading live metrics...</div>`;\r\n    document.getElementById(\"modalSchoolHealth\").textContent = \"Loading live school metrics...\";\r\n    loadSchoolMetrics(uid).then((metrics) => {\r\n      if (currentUID !== uid) return;\r\n      document.getElementById(\"schoolInsightGrid\").innerHTML = renderInsightGrid(metrics);\r\n      document.getElementById(\"modalSchoolHealth\").textContent =\r\n        `${metrics.students} students, ${metrics.teachers} teachers, ${metrics.todayEmails} mails today, ${metrics.writeEstimate} estimated app writes today`;\r\n    }).catch(() => {\r\n      document.getElementById(\"schoolInsightGrid\").innerHTML = `<div class=\"empty-state\" style=\"grid-column:1/-1;\">Unable to load metrics.</div>`;\r\n    });\r\n\r\n    // Master access toggle\r\n    const toggle = document.getElementById(\"masterAccessToggle\");\r\n    toggle.checked = currentData.access !== false;\r\n    updateAccessLabel();\r\n    document.getElementById(\"profileSchoolName\").value = currentData.schoolName || currentData.name || \"\";\r\n    document.getElementById(\"profileAdminName\").value = currentData.adminName || currentData.name || \"\";\r\n    document.getElementById(\"profileAdminEmail\").value = currentData.adminEmail || currentData.email || \"\";\r\n    document.getElementById(\"profilePhone\").value = currentData.phone || currentData.contactNumber || \"\";\r\n    document.getElementById(\"profileSchoolCode\").value = currentData.schoolCode || \"\";\r\n    document.getElementById(\"profileAddress\").value = currentData.address || \"\";\r\n    document.getElementById(\"profileSchoolLogo\").value = \"\";\r\n    const subscription = subscriptionState(currentData);\r\n    document.getElementById(\"subscriptionPlan\").value = subscription.plan;\r\n    document.getElementById(\"subscriptionStatus\").value = subscription.status === \"expired\" ? \"past_due\" : subscription.status;\r\n    document.getElementById(\"subscriptionExpiresAt\").value = subscription.expiresAt;\r\n    document.getElementById(\"paymentAmount\").value = \"\";\r\n    document.getElementById(\"paymentDate\").value = new Date().toISOString().slice(0, 10);\r\n    document.getElementById(\"paymentReference\").value = \"\";\r\n    document.getElementById(\"subscriptionSummary\").textContent = `${subscription.plan} · ${subscriptionLabel(currentData)}${subscription.blocked ? \" — school access is blocked\" : \"\"}`;\r\n    loadBillingHistory(uid);\r\n\r\n    // Build feature rows\r\n    const grid = document.getElementById(\"featuresGrid\");\r\n    const features = currentData.features || {};\r\n    grid.innerHTML = FEATURES.map(f => {\r\n      const enabled = features[f.key] !== false;\r\n      return `\r\n      <div class=\"feature-row\">\r\n        <div class=\"feature-row-left\">\r\n          <div class=\"feature-icon\" style=\"background:${f.color}\">${f.icon}</div>\r\n          <div class=\"feature-row-info\">\r\n            <strong>${f.label}</strong>\r\n            <span>${f.desc}</span>\r\n          </div>\r\n        </div>\r\n        <label class=\"mini-toggle\">\r\n          <input type=\"checkbox\" id=\"feat-${f.key}\" ${enabled ? \"checked\" : \"\"}>\r\n          <span class=\"mini-track\"></span>\r\n        </label>\r\n      </div>`;\r\n    }).join(\"\");\r\n\r\n    document.getElementById(\"featureModal\").classList.add(\"open\");\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\nasync function loadBillingHistory(uid) {\r\n  const target = document.getElementById(\"billingHistory\");\r\n  if (!target) return;\r\n  target.innerHTML = `<div class=\"billing-empty\">Loading records...</div>`;\r\n  try {\r\n    const snap = await getDocs(collection(db, \"schools\", uid, \"billingPayments\"));\r\n    const rows = snap.docs.map((item) => ({ id: item.id, ...item.data() }))\r\n      .sort((a, b) => String(b.paymentDate || b.createdAt || \"\").localeCompare(String(a.paymentDate || a.createdAt || \"\"))).slice(0, 8);\r\n    target.innerHTML = rows.length ? rows.map((payment) => `<div class=\"billing-item\"><div><strong>₹${Number(payment.amount || 0).toLocaleString(\"en-IN\")}</strong><span>${escapeHtml(payment.reference || \"Payment recorded\")}</span></div><span>${escapeHtml(payment.paymentDate || \"\")}</span></div>`).join(\"\") : `<div class=\"billing-empty\">No payments recorded for this school yet.</div>`;\r\n  } catch (_) {\r\n    target.innerHTML = `<div class=\"billing-empty\">Payment history could not be loaded.</div>`;\r\n  }\r\n}\r\n\r\n// ---- CLOSE MODAL ----\r\nwindow.closeModal = () => {\r\n  document.getElementById(\"featureModal\").classList.remove(\"open\");\r\n  currentUID = null;\r\n  currentData = null;\r\n};\r\n\r\n// Close on overlay click\r\ndocument.getElementById(\"featureModal\").addEventListener(\"click\", function(e) {\r\n  if (e.target === this) closeModal();\r\n});\r\n\r\ndocument.getElementById(\"schoolSearch\").addEventListener(\"input\", applySchoolFilters);\r\ndocument.getElementById(\"schoolStatusFilter\").addEventListener(\"change\", applySchoolFilters);\r\n\r\n// ---- UPDATE ACCESS LABEL ----\r\nwindow.updateAccessLabel = () => {\r\n  const checked = document.getElementById(\"masterAccessToggle\").checked;\r\n  document.getElementById(\"accessLabel\").textContent = checked ? \"Enabled\" : \"Disabled\";\r\n  document.getElementById(\"accessLabel\").style.color = checked ? \"#4ade80\" : \"#f87171\";\r\n};\r\n\r\n// ---- SAVE FEATURES ----\r\nwindow.saveFeatures = async () => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  if (!currentUID) return;\r\n  const saveBtn = document.querySelector(\".btn-save\");\r\n  saveBtn.textContent = \"Saving...\";\r\n  saveBtn.disabled = true;\r\n\r\n  try {\r\n    const newAccess = document.getElementById(\"masterAccessToggle\").checked;\r\n    const newFeatures = {};\r\n    FEATURES.forEach(f => {\r\n      newFeatures[f.key] = document.getElementById(\"feat-\" + f.key).checked;\r\n    });\r\n    const subscription = {\r\n      plan: document.getElementById(\"subscriptionPlan\").value,\r\n      status: document.getElementById(\"subscriptionStatus\").value,\r\n      expiresAt: document.getElementById(\"subscriptionExpiresAt\").value\r\n    };\r\n    if (!subscription.expiresAt) throw new Error(\"Set a licence expiry date before saving.\");\r\n    const paymentAmount = Number(document.getElementById(\"paymentAmount\").value || 0);\r\n    const paymentDate = document.getElementById(\"paymentDate\").value;\r\n    const paymentReference = document.getElementById(\"paymentReference\").value.trim();\r\n    if (paymentAmount > 0 && !paymentDate) throw new Error(\"Set a payment date for the recorded payment.\");\r\n    const schoolDetails = {\r\n      schoolName: document.getElementById(\"profileSchoolName\").value.trim(),\r\n      name: document.getElementById(\"profileSchoolName\").value.trim(),\r\n      adminName: document.getElementById(\"profileAdminName\").value.trim(),\r\n      phone: document.getElementById(\"profilePhone\").value.trim(),\r\n      contactNumber: document.getElementById(\"profilePhone\").value.trim(),\r\n      schoolCode: document.getElementById(\"profileSchoolCode\").value.trim(),\r\n      address: document.getElementById(\"profileAddress\").value.trim()\r\n    };\r\n    if (!schoolDetails.schoolName || !schoolDetails.adminName) throw new Error(\"School name and administrator name are required.\");\r\n    const replacementLogo = document.getElementById(\"profileSchoolLogo\").files?.[0] || null;\r\n    if (replacementLogo) {\r\n      const logoUpload = await uploadSchoolLogo(replacementLogo, schoolDetails.schoolName);\r\n      Object.assign(schoolDetails, logoUpload, { schoolLogoUrl: logoUpload.logoUrl });\r\n    }\r\n\r\n    await updateDoc(doc(db, \"users\", currentUID), {\r\n      access: newAccess,\r\n      features: newFeatures,\r\n      subscription,\r\n      ...schoolDetails,\r\n      name: schoolDetails.adminName\r\n    });\r\n    await setDoc(doc(db, \"schools\", currentUID), {\r\n      access: newAccess,\r\n      features: newFeatures,\r\n      subscription,\r\n      ...schoolDetails,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL\r\n    }, { merge: true });\r\n    if (replacementLogo) {\r\n      await setDoc(doc(db, \"schools\", currentUID, \"config\", \"branding\"), {\r\n        schoolName: schoolDetails.schoolName,\r\n        logoUrl: schoolDetails.logoUrl,\r\n        schoolLogoUrl: schoolDetails.schoolLogoUrl,\r\n        logoPublicId: schoolDetails.logoPublicId,\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL\r\n      }, { merge: true });\r\n    }\r\n    if (paymentAmount > 0) {\r\n      const paymentRef = doc(collection(db, \"schools\", currentUID, \"billingPayments\"));\r\n      await setDoc(paymentRef, { amount: paymentAmount, paymentDate, reference: paymentReference, plan: subscription.plan, recordedAt: new Date(), recordedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL });\r\n    }\r\n\r\n    showToast(\"Settings saved successfully\");\r\n    closeModal();\r\n    loadSchools();\r\n  } catch(e) {\r\n    showToast(e.message, \"error\");\r\n  } finally {\r\n    saveBtn.textContent = \"Save Changes\";\r\n    saveBtn.disabled = false;\r\n  }\r\n};\r\n\r\n// ---- DELETE SCHOOL ----\r\nwindow.deleteSchool = async (uid, name) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  if (!confirm(`Delete \"${name}\"?\\n\\nThis will remove their admin access permanently.`)) return;\r\n  try {\r\n    await deleteDoc(doc(db, \"users\", uid));\r\n    showToast(`\"${name}\" deleted`);\r\n    loadSchools();\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\n// ---- INIT ----\r\nonAuthStateChanged(auth, async (user) => {\r\n  if (!user) {\r\n    redirectUnauthorized();\r\n    return;\r\n  }\r\n  if (!isAuthorizedSuperAdmin(user)) {\r\n    await signOut(auth).catch(() => {});\r\n    redirectUnauthorized();\r\n    return;\r\n  }\r\n  try {\n    await setDoc(doc(db, \"users\", user.uid), {\n      uid: user.uid,\n      name: \"Ansh Bajpai\",\n      email: SUPER_ADMIN_EMAIL,\n      role: \"superAdmin\",\n      superAdmin: true,\n      access: true,\n      updatedAt: new Date()\n    }, { merge: true });\n  } catch (profileError) {\n    console.warn(\"Super admin profile bootstrap failed:\", profileError);\n  }\n  document.getElementById(\"signupExpiry\").value = defaultExpiryDate();\r\n  loadSchools();\r\n});\n</script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":"\r\n<style>\r\n/* Super admin workspace: restrained, light and operational */\r\n:root { --bg:#f6f8fb; --surface:#ffffff; --surface2:#ffffff; --line:#e4e9f0; --line2:#edf1f5; --text:#172033; --muted:#667085; --brand:#1d4ed8; --brand2:#1e40af; --danger:#b42318; --success:#067647; --warn:#b54708; }\r\nbody { display:block; padding:0; color:var(--text); background:var(--bg); background-image:none; }\r\n.workspace-header { height:72px; background:#fff; border-bottom:1px solid var(--line); display:flex; align-items:center; justify-content:space-between; padding:0 max(24px, calc((100vw - 1280px) / 2)); }\r\n.workspace-brand { display:flex; align-items:center; gap:12px; font-family:var(--font-head); font-weight:700; letter-spacing:-.03em; }\r\n.brand-mark { width:32px; height:32px; display:grid; place-items:center; background:#1d4ed8; color:#fff; font-size:13px; border-radius:7px; }\r\n.workspace-label { font-size:12px; color:var(--muted); font-family:var(--font-body); font-weight:600; letter-spacing:0; }\r\n.workspace-header .super-admin-top-actions { margin:0; }\r\n.super-admin-top-actions .eyebrow { display:none; }\r\n.super-admin-logout { border-color:#e5e7eb; border-radius:7px; background:#fff; color:#344054; padding:9px 14px; font-weight:600; }\r\n.super-admin-logout:hover { background:#f9fafb; border-color:#d0d5dd; }\r\n.shell { width:min(1280px,100%); padding:32px 24px 48px; grid-template-columns:minmax(0,1.55fr) minmax(340px,.9fr); gap:24px; }\r\n.panel { background:#fff; border:1px solid var(--line); border-radius:10px; backdrop-filter:none; box-shadow:0 1px 2px rgba(16,24,40,.03); overflow:visible; }\r\n.panel-body,.form-panel .panel-body { padding:26px; }\r\n.hero .super-admin-top-actions { display:none; }\r\n.eyebrow { color:#475467; font-family:var(--font-body); font-size:11px; letter-spacing:.08em; margin-bottom:9px; }\r\n.hero h1 { font-size:28px; color:#101828; margin-bottom:8px; letter-spacing:-.035em; }\r\n.hero p { color:var(--muted); font-size:14px; line-height:1.55; margin-bottom:22px; }\r\n.chips { display:none; }\r\n.admin-summary { display:grid; grid-template-columns:repeat(4,1fr); border:1px solid var(--line); margin:0 0 26px; }\r\n.summary-cell { padding:15px; border-right:1px solid var(--line); }\r\n.summary-cell:last-child { border:0; }\r\n.summary-cell span { display:block; color:var(--muted); font-size:11px; margin-bottom:5px; }\r\n.summary-cell strong { color:#101828; font:700 20px var(--font-head); letter-spacing:-.04em; }\r\n.school-toolbar { display:flex; gap:10px; align-items:center; margin-bottom:16px; }\r\n.school-search,.school-filter { height:36px; border:1px solid #d0d5dd; border-radius:6px; background:#fff; color:#344054; padding:0 10px; font:13px var(--font-body); outline:none; }\r\n.school-search { flex:1; }.school-search:focus,.school-filter:focus { border-color:#84adff; box-shadow:0 0 0 3px #eff4ff; }\r\n.list-head { margin-bottom:12px; }.list-head h3 { color:#101828; font-family:var(--font-head); font-size:15px; }.count-badge { background:#f2f4f7; color:#475467; border-radius:5px; padding:4px 8px; }\r\n.school-list { gap:10px; }.school-card { background:#fff; border:1px solid var(--line); border-radius:8px; }.school-card:hover { border-color:#b2ccff; box-shadow:0 2px 8px rgba(16,24,40,.05); }\r\n.card-main { padding:15px 16px 12px; }.school-avatar { width:38px; height:38px; border-radius:7px; background:#eff4ff; border-color:#d1e0ff; color:#1d4ed8; }.card-name { color:#101828; }.card-meta { color:#667085; font-size:12px; }.status-dot { border-radius:2px; box-shadow:none!important; }.school-card-stats { padding:0 15px 12px; gap:8px; }.school-card-stat { border-radius:5px; background:#f9fafb; border-color:#eaecf0; padding:8px; }.school-card-stat strong { color:#101828; font-family:var(--font-body); font-size:14px; }.school-card-stat span { color:#667085; }\r\n.card-actions { border-top-color:#eaecf0; padding:10px 15px; }.btn { border-radius:6px; padding:7px 10px; font-size:12px; background:#fff; }.btn-toggle-on,.btn-toggle-off,.btn-features,.btn-insights,.btn-delete { background:#fff; }.btn-toggle-on{color:#067647;border:1px solid #a6f4c5}.btn-toggle-off,.btn-delete{color:#b42318;border:1px solid #fecdca}.btn-features{color:#175cd3;border:1px solid #b2ccff}.btn-insights{color:#344054;border:1px solid #d0d5dd}\r\n.form-panel { position:sticky; top:20px; }.form-panel h2 { color:#101828; font-size:21px; }.form-panel .sub { color:var(--muted); font-size:13px; margin-bottom:22px; }.form-grid { gap:13px; }.field { gap:6px; }.field label,.logo-upload-copy label { color:#344054; font-size:12px; }.field input,.field select { background:#fff; border:1px solid #d0d5dd; color:#344054; border-radius:6px; padding:10px 11px; font-size:13px; }.field input::placeholder { color:#98a2b3; }.field input:focus { border-color:#84adff; box-shadow:0 0 0 3px #eff4ff; }.logo-upload-row { border-radius:7px; border-color:#d0d5dd; background:#f9fafb; padding:12px; }.school-logo-preview { border-radius:7px; background:#fff; border-color:#d0d5dd; color:#475467; }.logo-upload-copy small { color:#667085; font-size:11px; }.hint { color:#475467; background:#f9fafb; border-color:#eaecf0; border-radius:6px; font-size:12px; }.submit-btn { border-radius:6px; padding:11px; background:#1d4ed8; font-family:var(--font-body); font-size:13px; }\r\n.modal-overlay { background:rgba(16,24,40,.42); backdrop-filter:blur(3px); }.modal { background:#fff; border-color:#eaecf0; border-radius:10px; width:min(760px,100%); }.modal-header,.modal-footer { background:#fff; border-color:#eaecf0; }.modal-header { padding:20px 24px 16px; }.modal-title { color:#101828; }.modal-sub { color:#667085; }.modal-close { border-radius:5px; background:#f2f4f7; color:#475467; }.modal-body { padding:20px 24px; }.modal-logo { border-radius:7px; background:#eff4ff; border-color:#d1e0ff; color:#1d4ed8; }.insight-grid { grid-template-columns:repeat(4,1fr); }.insight-card { border-radius:6px; background:#f9fafb; border-color:#eaecf0; }.insight-card span{color:#667085}.insight-card strong{color:#101828}.control-note { border-radius:6px; color:#6941c6; background:#f9f5ff; border-color:#e9d7fe; }.access-row,.feature-row { background:#fff; border-color:#eaecf0; border-radius:6px; }.access-row-info strong,.feature-row-info strong { color:#344054; }.access-row-info span,.feature-row-info span { color:#667085; }.subscription-panel,.school-profile-panel { border-radius:6px; background:#f9fafb; border-color:#eaecf0; }.subscription-panel h3,.school-profile-panel h3,.billing-history h4 { color:#344054; }.school-profile-panel p { color:#667085; }.subscription-grid input,.subscription-grid select,.school-profile-grid input,.school-profile-grid textarea { border-radius:5px; border-color:#d0d5dd; }.school-profile-grid .profile-readonly { background:#f2f4f7; color:#667085; }.subscription-summary { border-radius:5px; background:#eff4ff; color:#175cd3; }.btn-cancel,.btn-save { border-radius:6px; }.btn-cancel { color:#344054; background:#fff; border-color:#d0d5dd; }.btn-save { background:#1d4ed8; }.features-head { color:#475467; font-family:var(--font-body); }.empty-state { border-radius:6px; color:#667085; }.toast { background:#fff; color:#344054; border-color:#d0d5dd; border-radius:7px; box-shadow:0 8px 24px rgba(16,24,40,.14); }\r\n.toggle,.mini-toggle { border-radius:4px; }.slider-track,.mini-track { border-radius:4px; background:#eaecf0; border-color:#d0d5dd; }.slider-track::before,.mini-track::before { border-radius:2px; }.toggle input:checked~.slider-track,.mini-toggle input:checked~.mini-track { background:#1d4ed8; border-color:#1d4ed8; }.toggle input:checked~.slider-track::before,.mini-toggle input:checked~.mini-track::before { background:#fff; }\r\n@media(max-width:900px){.shell{grid-template-columns:1fr}.form-panel{position:static}.workspace-header{padding:0 18px}.admin-summary{grid-template-columns:repeat(2,1fr)}.summary-cell:nth-child(2){border-right:0}.summary-cell:nth-child(-n+2){border-bottom:1px solid var(--line)}}\r\n@media(max-width:520px){.shell{padding:20px 14px}.panel-body,.form-panel .panel-body{padding:20px}.workspace-label{display:none}.admin-summary{grid-template-columns:repeat(2,1fr)}.school-toolbar{flex-wrap:wrap}.school-search{min-width:100%}.subscription-grid,.school-profile-grid{grid-template-columns:1fr}.insight-grid{grid-template-columns:repeat(2,1fr)}}\r\n"}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp }\r\n  from \"./firebase-compat.js\";\r\nimport { getAuth, createUserWithEmailAndPassword, onAuthStateChanged, signOut }\r\n  from \"./firebase-compat.js\";\r\nimport {\r\n  getFirestore, doc, setDoc, collection,\r\n  getDocs, updateDoc, deleteDoc, getDoc, query, where, limit\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\nconst db = getFirestore(app);\nconst adminCreatorApp = initializeApp(firebaseConfig, \"superAdminCreatorApp\");\nconst adminCreatorAuth = getAuth(adminCreatorApp);\nconst SUPER_ADMIN_EMAIL = \"anshbajpai4@gmail.com\";\nconst SUPABASE_URL = \"https://ezkmeedcqetztkeppxil.supabase.co\";\nconst SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\nconst CREATE_SCHOOL_ADMIN_URL = `${SUPABASE_URL}/functions/v1/create-school-admin`;\n\r\n// ---- FEATURE DEFINITIONS ----\r\nconst ICONS = {\r\n  dashboard: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 13h4v7H4v-7Zm6-9h4v16h-4V4Zm6 5h4v11h-4V9Z\"/></svg>`,\r\n  teachers: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-8 8a8 8 0 0 1 16 0H4Z\"/></svg>`,\r\n  students: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3 2 8l10 5 10-5-10-5Zm-7 9v4l7 4 7-4v-4l-7 3.5L5 12Z\"/></svg>`,\r\n  attendance: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 3h10v2h3v16H4V5h3V3Zm2 4H6v12h12V7h-3v2H9V7Zm1 6h6v2h-6v-2Z\"/></svg>`,\r\n  payroll: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 6h16v12H4V6Zm2 2v8h12V8H6Zm6 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z\"/></svg>`,\r\n  library: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 4h12a2 2 0 0 1 2 2v14H7a2 2 0 0 1-2-2V4Zm2 0v14h10V6H7Zm2 4h6v2H9V8Z\"/></svg>`,\r\n  timetable: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 2h2v3h6V2h2v3h3v17H4V5h3V2Zm-1 8v10h12V10H6Zm2 2h3v3H8v-3Z\"/></svg>`,\r\n  transport: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 4h12l2 5v8h-2a2 2 0 0 1-4 0h-4a2 2 0 0 1-4 0H4V9l2-5Zm1.2 2L6.4 8h11.2l-.8-2H7.2Z\"/></svg>`,\r\n  reports: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 5h7l2 2h7v12H4V5Zm3 8h10v-2H7v2Zm0 4h7v-2H7v2Z\"/></svg>`,\r\n  announcements: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 10v4h4l7 4V6l-7 4H4Zm13-1.5v7a4 4 0 0 0 0-7Z\"/></svg>`,\r\n  settings: `<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m19.4 13.5.1-1.5-.1-1.5 2-1.5-2-3.5-2.4 1a8 8 0 0 0-2.6-1.5L14 2h-4l-.4 2.5A8 8 0 0 0 7 6L4.6 5l-2 3.5 2 1.5-.1 1.5.1 1.5-2 1.5 2 3.5 2.4-1a8 8 0 0 0 2.6 1.5L10 22h4l.4-2.5A8 8 0 0 0 17 18l2.4 1 2-3.5-2-1.5ZM12 15.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7Z\"/></svg>`\r\n};\r\n\r\nconst FEATURES = [\r\n  { key: \"dashboard\",      label: \"Dashboard\",      desc: \"Main overview & stats\",       icon: ICONS.dashboard, color: \"rgba(59,110,248,0.12)\"  },\r\n  { key: \"teachers\",       label: \"Teachers\",        desc: \"Teacher management module\",   icon: ICONS.teachers, color: \"rgba(168,85,247,0.12)\" },\r\n  { key: \"students\",       label: \"Students\",        desc: \"Student records & profiles\",  icon: ICONS.students, color: \"rgba(20,184,166,0.12)\"  },\r\n  { key: \"attendance\",     label: \"Attendance\",      desc: \"Daily attendance tracking\",   icon: ICONS.attendance, color: \"rgba(245,158,11,0.12)\"  },\r\n  { key: \"payroll\",        label: \"Payroll\",         desc: \"Salary & payment processing\", icon: ICONS.payroll, color: \"rgba(34,197,94,0.12)\"   },\r\n  { key: \"library\",        label: \"Library\",         desc: \"Books, issues and returns\",    icon: ICONS.library, color: \"rgba(14,165,233,0.12)\"   },\r\n  { key: \"timetable\",      label: \"Timetable\",       desc: \"Class and teacher schedules\",  icon: ICONS.timetable, color: \"rgba(236,72,153,0.12)\" },\r\n  { key: \"transport\",      label: \"Transport\",       desc: \"Vehicles, routes and tracking\", icon: ICONS.transport, color: \"rgba(132,204,22,0.12)\" },\r\n  { key: \"reports\",        label: \"Reports\",         desc: \"Analytics & report exports\",  icon: ICONS.reports, color: \"rgba(239,68,68,0.12)\"   },\r\n  { key: \"announcements\",  label: \"Announcements\",   desc: \"School-wide notices\",         icon: ICONS.announcements, color: \"rgba(99,102,241,0.12)\"  },\r\n  { key: \"settings\",       label: \"Settings\",        desc: \"School config & branding\",    icon: ICONS.settings, color: \"rgba(100,116,139,0.12)\" },\r\n];\r\n// ---- CURRENT MODAL STATE ----\r\nlet currentUID = null;\r\nlet currentData = null;\r\nlet signupInProgress = false;\r\nconst CLOUDINARY_CLOUD_NAME = \"fthnumnk\";\r\nconst CLOUDINARY_UPLOAD_PRESET = \"schoolix_student_photos\";\r\n\r\nfunction isoDate(value) {\r\n  const date = toJsDate(value);\r\n  return date ? date.toISOString().slice(0, 10) : \"\";\r\n}\r\n\r\nfunction defaultExpiryDate() {\r\n  const date = new Date();\r\n  date.setFullYear(date.getFullYear() + 1);\r\n  return date.toISOString().slice(0, 10);\r\n}\r\n\r\nfunction subscriptionState(data = {}) {\r\n  const subscription = data.subscription || {};\r\n  const expiresAt = isoDate(subscription.expiresAt || data.subscriptionExpiresAt);\r\n  const status = String(subscription.status || \"active\").toLowerCase();\r\n  const expired = Boolean(expiresAt && new Date(`${expiresAt}T23:59:59`).getTime() < Date.now());\r\n  const blocked = [\"suspended\", \"cancelled\"].includes(status) || expired;\r\n  return { plan: subscription.plan || \"Growth\", status: expired ? \"expired\" : status, expiresAt, expired, blocked };\r\n}\r\n\r\nfunction subscriptionLabel(data = {}) {\r\n  const sub = subscriptionState(data);\r\n  if (sub.status === \"expired\") return `Expired ${sub.expiresAt || \"\"}`.trim();\r\n  if (sub.status === \"suspended\") return \"Suspended\";\r\n  if (sub.status === \"past_due\") return \"Payment due\";\r\n  if (sub.status === \"cancelled\") return \"Cancelled\";\r\n  return `Active · expires ${sub.expiresAt || \"not set\"}`;\r\n}\r\n\r\nfunction normalizeEmail(value = \"\") {\r\n  return String(value || \"\").trim().toLowerCase();\r\n}\r\n\r\nfunction isAuthorizedSuperAdmin(user) {\r\n  return normalizeEmail(user?.email) === SUPER_ADMIN_EMAIL;\r\n}\r\n\r\nfunction redirectUnauthorized() {\r\n  resetSchoolList(\"Super admin login required.\");\r\n  window.setTimeout(() => {\r\n    window.location.replace(\"#/index.html?access_error=\" + encodeURIComponent(\"Only the authorized Super Admin can access this page.\"));\r\n  }, 250);\r\n}\r\n\r\nfunction escapeHtml(value = \"\") {\r\n  return String(value ?? \"\")\r\n    .replace(/&/g, \"&amp;\")\r\n    .replace(/</g, \"&lt;\")\r\n    .replace(/>/g, \"&gt;\")\r\n    .replace(/\"/g, \"&quot;\")\r\n    .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction jsString(value = \"\") {\r\n  return String(value ?? \"\").replace(/\\\\/g, \"\\\\\\\\\").replace(/'/g, \"\\\\'\").replace(/\\n/g, \" \");\r\n}\r\n\r\nfunction renderLogo(url = \"\", fallback = \"S\") {\r\n  const safeUrl = String(url || \"\").trim();\r\n  return safeUrl ? `<img src=\"${escapeHtml(safeUrl)}\" alt=\"School logo\">` : escapeHtml(fallback || \"S\");\r\n}\r\n\r\nwindow.previewSchoolLogo = (event) => {\r\n  const file = event.target.files?.[0];\r\n  const preview = document.getElementById(\"schoolLogoPreview\");\r\n  if (!preview) return;\r\n  if (!file) {\r\n    preview.textContent = \"LOGO\";\r\n    return;\r\n  }\r\n  preview.innerHTML = `<img src=\"${URL.createObjectURL(file)}\" alt=\"School logo preview\">`;\r\n};\r\n\r\nasync function uploadSchoolLogo(file, schoolName) {\r\n  if (!file) return { logoUrl: \"\", logoPublicId: \"\" };\r\n  if (!file.type.startsWith(\"image/\")) throw new Error(\"Please select an image file for school logo.\");\r\n  if (file.size > 5 * 1024 * 1024) throw new Error(\"School logo must be under 5 MB.\");\r\n  const form = new FormData();\r\n  form.append(\"file\", file);\r\n  form.append(\"upload_preset\", CLOUDINARY_UPLOAD_PRESET);\r\n  form.append(\"folder\", \"schoolix/school_logos\");\r\n  form.append(\"public_id\", `${schoolName.replace(/[^a-zA-Z0-9_-]/g, \"_\")}_${Date.now()}`);\r\n  const response = await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(CLOUDINARY_CLOUD_NAME)}/image/upload`, {\r\n    method: \"POST\",\r\n    body: form\r\n  });\r\n  const data = await response.json().catch(() => ({}));\r\n  if (!response.ok) throw new Error(data.error?.message || \"School logo upload failed.\");\r\n  return { logoUrl: data.secure_url || data.url || \"\", logoPublicId: data.public_id || \"\" };\r\n}\r\n\r\n// ---- TOAST ----\r\nfunction showToast(msg, type = \"success\") {\r\n  const t = document.getElementById(\"toast\");\r\n  t.textContent = msg;\r\n  t.className = \"toast \" + type + \" show\";\r\n  setTimeout(() => t.className = \"toast\", 2800);\r\n}\r\n\r\nwindow.logoutSuperAdmin = async () => {\r\n  try {\r\n    await signOut(auth);\r\n    window.location.replace(\"#/index.html\");\r\n  } catch (error) {\r\n    showToast(error.message || \"Unable to logout.\", \"error\");\r\n  }\r\n};\r\n\r\n// ---- INITIALS ----\r\nfunction initials(name = \"\") {\r\n  return name.trim().split(\" \").slice(0,2).map(w => w[0]?.toUpperCase() || \"\").join(\"\");\r\n}\r\n\r\n// ---- SIGNUP ----\r\nwindow.signup = async () => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) {\r\n    showToast(\"Only authorized Super Admin can create schools.\", \"error\");\r\n    return;\r\n  }\r\n  if (signupInProgress) return;\r\n  const schoolName = document.getElementById(\"schoolName\").value.trim();\r\n  const adminName  = document.getElementById(\"adminName\").value.trim();\r\n  const email      = normalizeEmail(document.getElementById(\"email\").value);\r\n  const password   = document.getElementById(\"password\").value;\r\n  const logoFile   = document.getElementById(\"schoolLogo\")?.files?.[0] || null;\r\n  const plan = document.getElementById(\"signupPlan\").value;\r\n  const expiresAt = document.getElementById(\"signupExpiry\").value;\r\n\r\n  if (!schoolName || !adminName || !email || !password) {\r\n    showToast(\"Please fill all fields\", \"error\"); return;\r\n  }\r\n  if (password.length < 6) {\r\n    showToast(\"Password must be at least 6 characters\", \"error\"); return;\r\n  }\r\n  if (!expiresAt) {\r\n    showToast(\"Please set the school licence expiry date\", \"error\"); return;\r\n  }\r\n\r\n  const btn = document.querySelector(\".submit-btn\");\r\n  btn.textContent = \"Creating...\";\r\n  btn.disabled = true;\r\n  signupInProgress = true;\r\n\r\n  try {\r\n    const existing = await getDocs(query(collection(db, \"users\"), where(\"email\", \"==\", email), limit(1)));\r\n    if (!existing.empty) {\r\n      showToast(\"This admin email already has a school account.\", \"error\");\r\n      return;\r\n    }\r\n\r\n    // Default: all features ON\n    const defaultFeatures = {};\n    FEATURES.forEach(f => defaultFeatures[f.key] = true);\n\n    const logoUpload = await uploadSchoolLogo(logoFile, schoolName);\n    const token = await auth.currentUser?.getIdToken(true);\n    if (!token) throw new Error(\"Super admin session expired. Please login again.\");\n    const response = await fetch(CREATE_SCHOOL_ADMIN_URL, {\n      method: \"POST\",\n      headers: {\n        \"Content-Type\": \"application/json\",\n        \"apikey\": SUPABASE_ANON_KEY,\n        \"Authorization\": `Bearer ${token}`\n      },\n      body: JSON.stringify({\n        schoolName,\n        adminName,\n        email,\n        password,\n        logoUrl: logoUpload.logoUrl,\n        schoolLogoUrl: logoUpload.logoUrl,\n        logoPublicId: logoUpload.logoPublicId,\n        features: defaultFeatures,\r\n        subscription: { plan, status: \"active\", expiresAt }\r\n      })\n    });\n    const result = await response.json().catch(() => ({}));\n    if (!response.ok || !result.success) throw new Error(result.error || \"Unable to create admin account.\");\n\n    await setDoc(doc(db, \"schools\", result.uid), {\n      schoolName,\n      name: schoolName,\n      adminName,\n      adminEmail: email,\n      logoUrl: logoUpload.logoUrl,\r\n      schoolLogoUrl: logoUpload.logoUrl,\r\n      logoPublicId: logoUpload.logoPublicId,\r\n      access: true,\r\n      features: defaultFeatures,\r\n      subscription: { plan, status: \"active\", expiresAt },\r\n      onboardingRequired: true,\r\n      onboardingCompleted: false,\r\n      onboardingVersion: 1,\r\n      createdAt: new Date(),\r\n      createdBy: auth.currentUser?.uid || \"\",\r\n      createdByEmail: SUPER_ADMIN_EMAIL\n    }, { merge: true });\n    await setDoc(doc(db, \"users\", result.uid), {\r\n      access: true,\r\n      features: defaultFeatures,\r\n      subscription: { plan, status: \"active\", expiresAt },\r\n      updatedAt: new Date()\r\n    }, { merge: true });\r\n\n    showToast(`Admin created for ${schoolName}`);\n    [\"schoolName\",\"adminName\",\"email\",\"password\"].forEach(id => document.getElementById(id).value = \"\");\r\n    document.getElementById(\"signupExpiry\").value = defaultExpiryDate();\r\n    const logoInput = document.getElementById(\"schoolLogo\");\r\n    if (logoInput) logoInput.value = \"\";\r\n    const logoPreview = document.getElementById(\"schoolLogoPreview\");\r\n    if (logoPreview) logoPreview.textContent = \"LOGO\";\r\n    loadSchools();\r\n  } catch(e) {\r\n    showToast(e.message, \"error\");\r\n  } finally {\r\n    await signOut(adminCreatorAuth).catch(() => {});\r\n    signupInProgress = false;\r\n    btn.textContent = \"Create Admin Account\";\r\n    btn.disabled = false;\r\n  }\r\n};\r\n\r\nfunction resetSchoolList(message = \"Loading...\") {\r\n  const list = document.getElementById(\"schoolList\");\r\n  const countBadge = document.getElementById(\"schoolCount\");\r\n  countBadge.textContent = \"0 schools\";\r\n  list.innerHTML = `<div class=\"empty-state\">${message}</div>`;\r\n}\r\n\r\nfunction toJsDate(value) {\r\n  if (!value) return null;\r\n  if (typeof value.toDate === \"function\") return value.toDate();\r\n  if (typeof value.seconds === \"number\") return new Date(value.seconds * 1000);\r\n  const parsed = new Date(value);\r\n  return Number.isNaN(parsed.getTime()) ? null : parsed;\r\n}\r\n\r\nfunction isToday(value) {\r\n  const date = toJsDate(value);\r\n  if (!date) return false;\r\n  const today = new Date();\r\n  return date.getFullYear() === today.getFullYear() &&\r\n    date.getMonth() === today.getMonth() &&\r\n    date.getDate() === today.getDate();\r\n}\r\n\r\nasync function countCollection(pathParts) {\r\n  try {\r\n    const snap = await getDocs(collection(db, ...pathParts));\r\n    return snap.size;\r\n  } catch (_) {\r\n    return 0;\r\n  }\r\n}\r\n\r\nfunction teacherCountKey(data = {}, fallbackId = \"\") {\r\n  return String(\r\n    data.authUid ||\r\n    data.uid ||\r\n    data.teacherId ||\r\n    data.email ||\r\n    fallbackId ||\r\n    \"\"\r\n  ).trim().toLowerCase();\r\n}\r\n\r\nasync function countTeachersForSchool(uid, teachersSnap) {\r\n  const teacherKeys = new Set();\r\n  (teachersSnap.docs || []).forEach((item) => {\r\n    const key = teacherCountKey(item.data?.() || {}, item.id);\r\n    if (key) teacherKeys.add(key);\r\n  });\r\n\r\n  const userQueries = [\"teacher\", \"teachers\"].flatMap((teacherRole) => [\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminId\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"schoolId\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminUID\", \"==\", uid)),\r\n    query(collection(db, \"users\"), where(\"role\", \"==\", teacherRole), where(\"adminUid\", \"==\", uid))\r\n  ]);\r\n\r\n  const userSnaps = await Promise.all(userQueries.map((teacherQuery) => getDocs(teacherQuery).catch(() => ({ docs: [] }))));\r\n  userSnaps.forEach((snap) => {\r\n    (snap.docs || []).forEach((item) => {\r\n      const data = item.data?.() || {};\r\n      const key = teacherCountKey(data, item.id);\r\n      if (key) teacherKeys.add(key);\r\n    });\r\n  });\r\n\r\n  return teacherKeys.size;\r\n}\r\n\r\nasync function loadSchoolMetrics(uid) {\r\n  const [\r\n    studentsSnap,\r\n    teachersSnap,\r\n    attendanceSnap,\r\n    feesSnap,\r\n    reportsSnap,\r\n    notificationsSnap,\r\n    devicesSnap,\r\n    accountsSnap\r\n  ] = await Promise.all([\r\n    getDocs(collection(db, \"schools\", uid, \"students\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"teachers\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"attendance\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"fees\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"reportCards\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"notifications\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"notificationDevices\")).catch(() => ({ docs: [], size: 0 })),\r\n    getDocs(collection(db, \"schools\", uid, \"accounts\")).catch(() => ({ docs: [], size: 0 }))\r\n  ]);\r\n  const attendanceRows = attendanceSnap.docs.map((item) => item.data());\r\n  const notificationRows = notificationsSnap.docs.map((item) => item.data());\r\n  const todayAttendance = attendanceRows.filter((item) => isToday(item.date || item.timestamp || item.createdAt));\r\n  const todayAbsent = todayAttendance.filter((item) => String(item.status || \"\").toLowerCase() === \"absent\");\r\n  const todayEmails = attendanceRows.filter((item) => item.absenceEmailSent === true && isToday(item.absenceEmailSentAt || item.timestamp || item.date));\r\n  const todayNotifications = notificationRows.filter((item) => isToday(item.createdAt));\r\n  const writeEstimate = todayAttendance.length + todayNotifications.length + todayEmails.length;\r\n  const teacherCount = await countTeachersForSchool(uid, teachersSnap);\r\n  return {\r\n    students: studentsSnap.size,\r\n    teachers: teacherCount,\r\n    attendance: attendanceSnap.size,\r\n    todayAttendance: todayAttendance.length,\r\n    todayAbsent: todayAbsent.length,\r\n    todayEmails: todayEmails.length,\r\n    fees: feesSnap.size,\r\n    reports: reportsSnap.size,\r\n    notifications: notificationsSnap.size,\r\n    todayNotifications: todayNotifications.length,\r\n    devices: devicesSnap.size,\r\n    accounts: accountsSnap.size,\r\n    writeEstimate\r\n  };\r\n}\r\n\r\nfunction renderInsightGrid(metrics = {}) {\r\n  const rows = [\r\n    [\"Students\", metrics.students || 0],\r\n    [\"Teachers\", metrics.teachers || 0],\r\n    [\"Today attendance\", metrics.todayAttendance || 0],\r\n    [\"Today absent\", metrics.todayAbsent || 0],\r\n    [\"Emails today\", metrics.todayEmails || 0],\r\n    [\"Push today\", metrics.todayNotifications || 0],\r\n    [\"Reports\", metrics.reports || 0],\r\n    [\"Fee records\", metrics.fees || 0],\r\n    [\"Devices\", metrics.devices || 0],\r\n    [\"Accounts\", metrics.accounts || 0],\r\n    [\"Audit writes est.\", metrics.writeEstimate || 0],\r\n    [\"Total attendance\", metrics.attendance || 0]\r\n  ];\r\n  return rows.map(([label, value]) => `<div class=\"insight-card\"><span>${label}</span><strong>${Number(value || 0).toLocaleString(\"en-IN\")}</strong></div>`).join(\"\");\r\n}\r\n\r\nfunction updatePortfolioSummary(schools = []) {\r\n  const active = schools.filter((school) => school.access !== false && !subscriptionState(school).blocked).length;\r\n  const attention = schools.filter((school) => {\r\n    const state = subscriptionState(school);\r\n    return state.status === \"past_due\" || state.expired || state.blocked || school.access === false;\r\n  }).length;\r\n  document.getElementById(\"summaryTotal\").textContent = schools.length.toLocaleString(\"en-IN\");\r\n  document.getElementById(\"summaryActive\").textContent = active.toLocaleString(\"en-IN\");\r\n  document.getElementById(\"summaryAttention\").textContent = attention.toLocaleString(\"en-IN\");\r\n}\r\n\r\nfunction applySchoolFilters() {\r\n  const search = String(document.getElementById(\"schoolSearch\")?.value || \"\").trim().toLowerCase();\r\n  const filter = String(document.getElementById(\"schoolStatusFilter\")?.value || \"all\");\r\n  document.querySelectorAll(\".school-card\").forEach((card) => {\r\n    const matchesSearch = !search || String(card.dataset.search || \"\").includes(search);\r\n    const matchesStatus = filter === \"all\" || card.dataset.status === filter;\r\n    card.hidden = !(matchesSearch && matchesStatus);\r\n  });\r\n}\r\n\r\n// ---- LOAD SCHOOLS ----\r\nasync function loadSchools() {\r\n  const list = document.getElementById(\"schoolList\");\r\n  const countBadge = document.getElementById(\"schoolCount\");\r\n  list.innerHTML = `<div class=\"empty-state\">Loading...</div>`;\r\n\r\n  try {\r\n    const snap = await getDocs(collection(db, \"users\"));\r\n    const schools = [];\r\n    snap.forEach(d => {\r\n      const data = d.data();\r\n      if (data.schoolName && String(data.role || \"\").toLowerCase() === \"admin\") schools.push({ uid: d.id, ...data });\r\n    });\r\n\r\n    countBadge.textContent = schools.length + \" school\" + (schools.length !== 1 ? \"s\" : \"\");\r\n    updatePortfolioSummary(schools);\r\n\r\n    if (!schools.length) {\r\n      list.innerHTML = `<div class=\"empty-state\">No schools registered yet.</div>`;\r\n      return;\r\n    }\r\n\r\n    const metricEntries = await Promise.all(schools.map(async (school) => [school.uid, await loadSchoolMetrics(school.uid)]));\r\n    const metricsBySchool = Object.fromEntries(metricEntries);\r\n\r\n    list.innerHTML = schools.map(s => {\r\n      const subscription = subscriptionState(s);\r\n      const on = s.access !== false && !subscription.blocked;\r\n      const portfolioStatus = !on ? \"blocked\" : (subscription.status === \"past_due\" ? \"attention\" : \"active\");\r\n      const ini = initials(s.schoolName);\r\n      const featOn = s.features ? Object.values(s.features).filter(Boolean).length : FEATURES.length;\r\n      const metrics = metricsBySchool[s.uid] || {};\r\n      return `\r\n      <div class=\"school-card\" id=\"card-${s.uid}\" data-status=\"${portfolioStatus}\" data-search=\"${escapeHtml(`${s.schoolName || \"\"} ${s.email || \"\"} ${s.adminEmail || \"\"}`).toLowerCase()}\">\r\n        <div class=\"card-main\">\r\n          <div class=\"school-avatar\">${renderLogo(s.logoUrl || s.schoolLogoUrl || \"\", ini)}</div>\r\n          <div class=\"card-info\">\r\n            <div class=\"card-name\">${escapeHtml(s.schoolName)}</div>\r\n            <div class=\"card-meta\">\r\n              <span class=\"status-dot ${on ? 'on' : 'off'}\"></span>\r\n              ${on ? \"Access Enabled\" : \"Access blocked\"} &nbsp;|&nbsp;\r\n              ${featOn}/${FEATURES.length} modules\r\n            </div>\r\n            <div class=\"card-meta\" style=\"margin-top:4px;color:${subscription.blocked ? '#f87171' : '#94a3b8'}\">${escapeHtml(subscriptionLabel(s))}</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"school-card-stats\">\r\n          <div class=\"school-card-stat\"><strong>${metrics.students || 0}</strong><span>Students</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.teachers || 0}</strong><span>Teachers</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.todayEmails || 0}</strong><span>Mails today</span></div>\r\n          <div class=\"school-card-stat\"><strong>${metrics.writeEstimate || 0}</strong><span>Ops today</span></div>\r\n        </div>\r\n        <div class=\"card-actions\">\r\n          <button class=\"btn ${on ? 'btn-toggle-on' : 'btn-toggle-off'}\"\r\n            onclick=\"quickToggle('${s.uid}', ${on})\">\r\n            ${on ? \"Disable\" : \"Enable\"}\r\n          </button>\r\n          <button class=\"btn btn-features\"\r\n            onclick=\"openModal('${s.uid}')\">\r\n            Manage school\r\n          </button>\r\n          <button class=\"btn btn-delete\"\r\n            onclick=\"deleteSchool('${s.uid}', '${jsString(s.schoolName)}')\">\r\n            Delete\r\n          </button>\r\n        </div>\r\n      </div>`;\r\n    }).join(\"\");\r\n    applySchoolFilters();\r\n  } catch(e) {\r\n    list.innerHTML = `<div class=\"empty-state\">Failed to load schools.</div>`;\r\n    console.error(e);\r\n  }\r\n}\r\n\r\n// ---- QUICK TOGGLE ACCESS ----\r\nwindow.quickToggle = async (uid, currentAccess) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  try {\r\n    await updateDoc(doc(db, \"users\", uid), { access: !currentAccess });\r\n    await setDoc(doc(db, \"schools\", uid), { access: !currentAccess, updatedAt: new Date() }, { merge: true });\r\n    showToast(currentAccess ? \"Access disabled\" : \"Access enabled\");\r\n    loadSchools();\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\n// ---- OPEN MODAL ----\r\nwindow.openModal = async (uid) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  currentUID = uid;\r\n  try {\r\n    const snap = await getDoc(doc(db, \"users\", uid));\r\n    if (!snap.exists()) { showToast(\"School not found\", \"error\"); return; }\r\n    const schoolSnap = await getDoc(doc(db, \"schools\", uid)).catch(() => null);\r\n    currentData = { ...(schoolSnap?.exists?.() ? schoolSnap.data() : {}), ...snap.data() };\r\n\r\n    document.getElementById(\"modalSchoolName\").textContent = currentData.schoolName;\r\n    document.getElementById(\"modalSchoolEmail\").textContent = currentData.email;\r\n    document.getElementById(\"modalSchoolLogo\").innerHTML = renderLogo(currentData.logoUrl || currentData.schoolLogoUrl || \"\", initials(currentData.schoolName));\r\n    document.getElementById(\"schoolInsightGrid\").innerHTML = `<div class=\"empty-state\" style=\"grid-column:1/-1;\">Loading live metrics...</div>`;\r\n    document.getElementById(\"modalSchoolHealth\").textContent = \"Loading live school metrics...\";\r\n    loadSchoolMetrics(uid).then((metrics) => {\r\n      if (currentUID !== uid) return;\r\n      document.getElementById(\"schoolInsightGrid\").innerHTML = renderInsightGrid(metrics);\r\n      document.getElementById(\"modalSchoolHealth\").textContent =\r\n        `${metrics.students} students, ${metrics.teachers} teachers, ${metrics.todayEmails} mails today, ${metrics.writeEstimate} estimated app writes today`;\r\n    }).catch(() => {\r\n      document.getElementById(\"schoolInsightGrid\").innerHTML = `<div class=\"empty-state\" style=\"grid-column:1/-1;\">Unable to load metrics.</div>`;\r\n    });\r\n\r\n    // Master access toggle\r\n    const toggle = document.getElementById(\"masterAccessToggle\");\r\n    toggle.checked = currentData.access !== false;\r\n    updateAccessLabel();\r\n    document.getElementById(\"profileSchoolName\").value = currentData.schoolName || currentData.name || \"\";\r\n    document.getElementById(\"profileAdminName\").value = currentData.adminName || currentData.name || \"\";\r\n    document.getElementById(\"profileAdminEmail\").value = currentData.adminEmail || currentData.email || \"\";\r\n    document.getElementById(\"profilePhone\").value = currentData.phone || currentData.contactNumber || \"\";\r\n    document.getElementById(\"profileSchoolCode\").value = currentData.schoolCode || \"\";\r\n    document.getElementById(\"profileAddress\").value = currentData.address || \"\";\r\n    document.getElementById(\"profileSchoolLogo\").value = \"\";\r\n    const subscription = subscriptionState(currentData);\r\n    document.getElementById(\"subscriptionPlan\").value = subscription.plan;\r\n    document.getElementById(\"subscriptionStatus\").value = subscription.status === \"expired\" ? \"past_due\" : subscription.status;\r\n    document.getElementById(\"subscriptionExpiresAt\").value = subscription.expiresAt;\r\n    document.getElementById(\"paymentAmount\").value = \"\";\r\n    document.getElementById(\"paymentDate\").value = new Date().toISOString().slice(0, 10);\r\n    document.getElementById(\"paymentReference\").value = \"\";\r\n    document.getElementById(\"subscriptionSummary\").textContent = `${subscription.plan} · ${subscriptionLabel(currentData)}${subscription.blocked ? \" — school access is blocked\" : \"\"}`;\r\n    loadBillingHistory(uid);\r\n\r\n    // Build feature rows\r\n    const grid = document.getElementById(\"featuresGrid\");\r\n    const features = currentData.features || {};\r\n    grid.innerHTML = FEATURES.map(f => {\r\n      const enabled = features[f.key] !== false;\r\n      return `\r\n      <div class=\"feature-row\">\r\n        <div class=\"feature-row-left\">\r\n          <div class=\"feature-icon\" style=\"background:${f.color}\">${f.icon}</div>\r\n          <div class=\"feature-row-info\">\r\n            <strong>${f.label}</strong>\r\n            <span>${f.desc}</span>\r\n          </div>\r\n        </div>\r\n        <label class=\"mini-toggle\">\r\n          <input type=\"checkbox\" id=\"feat-${f.key}\" ${enabled ? \"checked\" : \"\"}>\r\n          <span class=\"mini-track\"></span>\r\n        </label>\r\n      </div>`;\r\n    }).join(\"\");\r\n\r\n    document.getElementById(\"featureModal\").classList.add(\"open\");\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\nasync function loadBillingHistory(uid) {\r\n  const target = document.getElementById(\"billingHistory\");\r\n  if (!target) return;\r\n  target.innerHTML = `<div class=\"billing-empty\">Loading records...</div>`;\r\n  try {\r\n    const snap = await getDocs(collection(db, \"schools\", uid, \"billingPayments\"));\r\n    const rows = snap.docs.map((item) => ({ id: item.id, ...item.data() }))\r\n      .sort((a, b) => String(b.paymentDate || b.createdAt || \"\").localeCompare(String(a.paymentDate || a.createdAt || \"\"))).slice(0, 8);\r\n    target.innerHTML = rows.length ? rows.map((payment) => `<div class=\"billing-item\"><div><strong>₹${Number(payment.amount || 0).toLocaleString(\"en-IN\")}</strong><span>${escapeHtml(payment.reference || \"Payment recorded\")}</span></div><span>${escapeHtml(payment.paymentDate || \"\")}</span></div>`).join(\"\") : `<div class=\"billing-empty\">No payments recorded for this school yet.</div>`;\r\n  } catch (_) {\r\n    target.innerHTML = `<div class=\"billing-empty\">Payment history could not be loaded.</div>`;\r\n  }\r\n}\r\n\r\n// ---- CLOSE MODAL ----\r\nwindow.closeModal = () => {\r\n  document.getElementById(\"featureModal\").classList.remove(\"open\");\r\n  currentUID = null;\r\n  currentData = null;\r\n};\r\n\r\n// Close on overlay click\r\ndocument.getElementById(\"featureModal\").addEventListener(\"click\", function(e) {\r\n  if (e.target === this) closeModal();\r\n});\r\n\r\ndocument.getElementById(\"schoolSearch\").addEventListener(\"input\", applySchoolFilters);\r\ndocument.getElementById(\"schoolStatusFilter\").addEventListener(\"change\", applySchoolFilters);\r\n\r\n// ---- UPDATE ACCESS LABEL ----\r\nwindow.updateAccessLabel = () => {\r\n  const checked = document.getElementById(\"masterAccessToggle\").checked;\r\n  document.getElementById(\"accessLabel\").textContent = checked ? \"Enabled\" : \"Disabled\";\r\n  document.getElementById(\"accessLabel\").style.color = checked ? \"#4ade80\" : \"#f87171\";\r\n};\r\n\r\n// ---- SAVE FEATURES ----\r\nwindow.saveFeatures = async () => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  if (!currentUID) return;\r\n  const saveBtn = document.querySelector(\".btn-save\");\r\n  saveBtn.textContent = \"Saving...\";\r\n  saveBtn.disabled = true;\r\n\r\n  try {\r\n    const newAccess = document.getElementById(\"masterAccessToggle\").checked;\r\n    const newFeatures = {};\r\n    FEATURES.forEach(f => {\r\n      newFeatures[f.key] = document.getElementById(\"feat-\" + f.key).checked;\r\n    });\r\n    const subscription = {\r\n      plan: document.getElementById(\"subscriptionPlan\").value,\r\n      status: document.getElementById(\"subscriptionStatus\").value,\r\n      expiresAt: document.getElementById(\"subscriptionExpiresAt\").value\r\n    };\r\n    if (!subscription.expiresAt) throw new Error(\"Set a licence expiry date before saving.\");\r\n    const paymentAmount = Number(document.getElementById(\"paymentAmount\").value || 0);\r\n    const paymentDate = document.getElementById(\"paymentDate\").value;\r\n    const paymentReference = document.getElementById(\"paymentReference\").value.trim();\r\n    if (paymentAmount > 0 && !paymentDate) throw new Error(\"Set a payment date for the recorded payment.\");\r\n    const schoolDetails = {\r\n      schoolName: document.getElementById(\"profileSchoolName\").value.trim(),\r\n      name: document.getElementById(\"profileSchoolName\").value.trim(),\r\n      adminName: document.getElementById(\"profileAdminName\").value.trim(),\r\n      phone: document.getElementById(\"profilePhone\").value.trim(),\r\n      contactNumber: document.getElementById(\"profilePhone\").value.trim(),\r\n      schoolCode: document.getElementById(\"profileSchoolCode\").value.trim(),\r\n      address: document.getElementById(\"profileAddress\").value.trim()\r\n    };\r\n    if (!schoolDetails.schoolName || !schoolDetails.adminName) throw new Error(\"School name and administrator name are required.\");\r\n    const replacementLogo = document.getElementById(\"profileSchoolLogo\").files?.[0] || null;\r\n    if (replacementLogo) {\r\n      const logoUpload = await uploadSchoolLogo(replacementLogo, schoolDetails.schoolName);\r\n      Object.assign(schoolDetails, logoUpload, { schoolLogoUrl: logoUpload.logoUrl });\r\n    }\r\n\r\n    await updateDoc(doc(db, \"users\", currentUID), {\r\n      access: newAccess,\r\n      features: newFeatures,\r\n      subscription,\r\n      ...schoolDetails,\r\n      name: schoolDetails.adminName\r\n    });\r\n    await setDoc(doc(db, \"schools\", currentUID), {\r\n      access: newAccess,\r\n      features: newFeatures,\r\n      subscription,\r\n      ...schoolDetails,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL\r\n    }, { merge: true });\r\n    if (replacementLogo) {\r\n      await setDoc(doc(db, \"schools\", currentUID, \"config\", \"branding\"), {\r\n        schoolName: schoolDetails.schoolName,\r\n        logoUrl: schoolDetails.logoUrl,\r\n        schoolLogoUrl: schoolDetails.schoolLogoUrl,\r\n        logoPublicId: schoolDetails.logoPublicId,\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL\r\n      }, { merge: true });\r\n    }\r\n    if (paymentAmount > 0) {\r\n      const paymentRef = doc(collection(db, \"schools\", currentUID, \"billingPayments\"));\r\n      await setDoc(paymentRef, { amount: paymentAmount, paymentDate, reference: paymentReference, plan: subscription.plan, recordedAt: new Date(), recordedBy: auth.currentUser?.email || SUPER_ADMIN_EMAIL });\r\n    }\r\n\r\n    showToast(\"Settings saved successfully\");\r\n    closeModal();\r\n    loadSchools();\r\n  } catch(e) {\r\n    showToast(e.message, \"error\");\r\n  } finally {\r\n    saveBtn.textContent = \"Save Changes\";\r\n    saveBtn.disabled = false;\r\n  }\r\n};\r\n\r\n// ---- DELETE SCHOOL ----\r\nwindow.deleteSchool = async (uid, name) => {\r\n  if (!isAuthorizedSuperAdmin(auth.currentUser)) return showToast(\"Unauthorized access.\", \"error\");\r\n  if (!confirm(`Delete \"${name}\"?\\n\\nThis will remove their admin access permanently.`)) return;\r\n  try {\r\n    await deleteDoc(doc(db, \"users\", uid));\r\n    showToast(`\"${name}\" deleted`);\r\n    loadSchools();\r\n  } catch(e) { showToast(e.message, \"error\"); }\r\n};\r\n\r\n// ---- INIT ----\r\nonAuthStateChanged(auth, async (user) => {\r\n  if (!user) {\r\n    redirectUnauthorized();\r\n    return;\r\n  }\r\n  if (!isAuthorizedSuperAdmin(user)) {\r\n    await signOut(auth).catch(() => {});\r\n    redirectUnauthorized();\r\n    return;\r\n  }\r\n  try {\n    await setDoc(doc(db, \"users\", user.uid), {\n      uid: user.uid,\n      name: \"Ansh Bajpai\",\n      email: SUPER_ADMIN_EMAIL,\n      role: \"superAdmin\",\n      superAdmin: true,\n      access: true,\n      updatedAt: new Date()\n    }, { merge: true });\n  } catch (profileError) {\n    console.warn(\"Super admin profile bootstrap failed:\", profileError);\n  }\n  document.getElementById(\"signupExpiry\").value = defaultExpiryDate();\r\n  loadSchools();\r\n});\n"},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
